namespace CodeProtection
{

    /// AUTO GENERATED by the Code Protection panel (Save button). Do not edit by
    /// hand. Change the "Integrity passphrase" field in Tools > Code Protection and
    /// press Save, which rewrites this file and the build time signer so the two
    /// always match.
    ///
    /// The secret is stored as a masked byte array rather than a plain string so a
    /// simple "strings" scan of the shipped game does not reveal it. This raises
    /// the bar against casual extraction. It cannot hide the value from a
    /// determined attacker, because the game must reconstruct it at runtime (see
    /// the README). It stops trivial file edits, not a resourced reverse engineer.

    public static class IntegritySecret
    {
        const byte Mask = 0x5A;
        static readonly byte[] Data = { 0x1A, 0x39, 0x51, 0x7B, 0x8B, 0xB9, 0xCF, 0xFF, 0x88, 0x09, 0x22 };
        static string _value;

        /// Name of the signed manifest file. Randomized per project on Save.
        public const string ManifestFileName = "integrity.manifest.json";

        public static string Value
        {
            get
            {
                if (_value != null) return _value;
                var b = new byte[Data.Length];
                for (int i = 0; i < Data.Length; i++)
                    b[i] = (byte)(Data[i] ^ Mask ^ (byte)((i * 31 + 7) & 0xFF));
                _value = System.Text.Encoding.UTF8.GetString(b);
                return _value;
            }
        }
    }
}
